public class BpoForkSchedule {
  // Uses TreeMap (ascending order) with floorEntry for lookup
  private final NavigableMap<UInt64, BlobParameters> epochToBlobParameters = new TreeMap<>();

  public Optional<BlobParameters> getBpoFork(final UInt64 epoch) {
    // floorEntry returns greatest key <= epoch (ascending TreeMap, floor = latest applicable)
    return Optional.ofNullable(epochToBlobParameters.floorEntry(epoch)).map(Map.Entry::getValue);
  }
}
// Note: Uses ascending TreeMap + floorEntry, equivalent to descending sort + first match.
// floorEntry(epoch) finds the greatest epoch key <= queried epoch = most recent applicable params.

